function normalizeCashEntries(entries){return entries.map(x=>{const status=x.status|| (x.type==='entrada'?'recebido':'pago');return {...x,status,dueDate:x.dueDate||x.date||'',settledAt:x.settledAt||(['recebido','pago'].includes(status)?(x.date||''):'')}})}
const fmt=n=>(Number(n)||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const newId=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const newUserId=(reserved=new Set())=>{const used=new Set([...(db.usedUserIds||[]).map(String),...db.clients.map(c=>String(c.publicId||'')),...reserved]);let id;do{id=String(Math.floor(10000000+Math.random()*90000000))}while(used.has(id));db.usedUserIds=[...new Set([...(db.usedUserIds||[]).map(String),id])];localStorage.setItem(DB_KEY,JSON.stringify(db));return id};
function load(){const empty=()=>({clients:[],quotes:[],parts:defaults.map((p,i)=>({id:'d'+i,category:p[0],name:p[2],price:p[3],qty:1})),catalog:[],components:[],notes:[],cashEntries:[],serviceOrders:[],downloads:defaultDownloads.map(x=>({...x})),usedUserIds:[]});try{const d=JSON.parse(localStorage.getItem(DB_KEY));if(!d)return empty();return {clients:Array.isArray(d.clients)?d.clients:[],quotes:Array.isArray(d.quotes)?d.quotes:[],parts:Array.isArray(d.parts)?d.parts:empty().parts,catalog:Array.isArray(d.catalog)?d.catalog:[],components:Array.isArray(d.components)?d.components:[],notes:Array.isArray(d.notes)?d.notes:[],cashEntries:Array.isArray(d.cashEntries)?normalizeCashEntries(d.cashEntries):[],serviceOrders:Array.isArray(d.serviceOrders)?d.serviceOrders:[],downloads:Array.isArray(d.downloads)?d.downloads:defaultDownloads.map(x=>({...x})),usedUserIds:Array.isArray(d.usedUserIds)?d.usedUserIds.map(String):[]}}catch{return empty()}}
let db=load(),toastTimer;db.downloads=db.downloads.filter(x=>String(x.name||'').trim().toLocaleLowerCase('pt-BR')!=='wlensky');function normalizeUserIds(){const seen=new Set();for(const c of db.clients){let id=String(c.publicId||'');if(!/^\d{8}$/.test(id)||seen.has(id)){c.publicId=newUserId(seen);id=c.publicId}seen.add(id)}db.usedUserIds=[...new Set([...(db.usedUserIds||[]).map(String),...seen])];for(const q of db.quotes){const client=db.clients.find(c=>c.id===q.client);if(client&&q.formData)q.formData.cliente_id=client.publicId}}normalizeUserIds();localStorage.setItem(DB_KEY,JSON.stringify(db));function writeAutoBackup(){try{localStorage.setItem(AUTO_BACKUP_KEY,JSON.stringify({savedAt:new Date().toISOString(),data:db,draft:localStorage.getItem('santorytec_orcamento_brindes_data')}))}catch{}}if(!localStorage.getItem(AUTO_BACKUP_KEY))writeAutoBackup();function persist(){localStorage.setItem(DB_KEY,JSON.stringify(db));writeAutoBackup();render()}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function initials(name){return name.split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()}
function dateText(iso){const value=String(iso||'');const date=/^\d{4}-\d{2}-\d{2}$/.test(value)?new Date(`${value}T12:00:00`):new Date(value);return date.toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'})}
function dateTimeText(iso){const value=String(iso||'');const date=/^\d{4}-\d{2}-\d{2}$/.test(value)?new Date(`${value}T12:00:00`):new Date(value);if(Number.isNaN(date.getTime()))return 'Data não informada';return date.toLocaleString('pt-BR',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})}
function go(page){$$('.page').forEach(p=>p.classList.toggle('active',p.id===`page-${page}`));$$('.nav-link').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('#crumb').textContent=({inicio:'Visão geral',clientes:'Clientes','ordens-servico':'Ordens de serviço',orcamentos:'Orçamentos',financeiro:'Fluxo de caixa',pecas:'Montador de PCs',catalogo:'Catálogo',anotacoes:'Anotações',relatorios:'Relatórios',downloads:'Downloads',configuracoes:'Configurações'})[page]||page;location.hash=page;if(page==='relatorios'&&typeof sendReportClient==='function')sendReportClient();if(page==='financeiro'&&typeof renderCashflow==='function')renderCashflow();window.scrollTo(0,0)}
$$('[data-page]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();go(a.dataset.page)}));$$('[data-go]').forEach(a=>a.addEventListener('click',()=>go(a.dataset.go)));window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(['inicio','clientes','ordens-servico','orcamentos','financeiro','pecas','catalogo','anotacoes','relatorios','downloads','configuracoes'].includes(p))go(p)});
function render(){$('#clientCount').textContent=db.clients.length;$('#quoteCount').textContent=db.quotes.length;$('#quoteTotal').textContent=fmt(db.quotes.reduce((s,q)=>s+(Number(q.value)||0),0));$('#clientSummary').textContent=`${db.clients.length} ${db.clients.length===1?'cliente':'clientes'}`;$('#quoteSummary').textContent=`${db.quotes.length} ${db.quotes.length===1?'proposta':'propostas'}`;
const term=($('#clientSearch')?.value||'').toLocaleLowerCase('pt-BR');const clients=db.clients.filter(c=>[c.name,c.publicId,c.email,c.phone,c.whatsapp,c.address,c.notes].join(' ').toLocaleLowerCase('pt-BR').includes(term));$('#clientRows').innerHTML=clients.map(c=>{const history=clientHistoryItems(c),quotes=history.filter(x=>x.kind==='Orçamento').length,orders=history.filter(x=>x.kind==='Ordem de serviço').length;return `<tr><td><span class="user-code">${esc(c.publicId||'—')}</span></td><td><div class="client-cell"><span class="client-avatar">${esc(initials(c.name))}</span><span><b>${esc(c.name)}</b><small class="client-email">${esc(c.email||'')}</small></span></div></td><td class="client-contact-cell">${c.phone?`<span>Tel. ${esc(c.phone)}</span>`:''}${c.whatsapp?`<span>WhatsApp ${esc(c.whatsapp)}</span>`:''}${!c.phone&&!c.whatsapp?'—':''}</td><td class="client-address-cell">${esc(c.address||'—')}</td><td><span class="client-history-count">${quotes} orç. · ${orders} OS</span></td><td>${dateText(c.created)}</td><td><div class="client-row-actions"><button class="client-row-action" data-client-history="${esc(c.id)}">Histórico</button><button class="client-row-action" data-edit-client="${esc(c.id)}">Editar</button><button class="table-action" data-delete-client="${esc(c.id)}" title="Excluir cliente">×</button></div></td></tr>`}).join('');$('#clientEmpty').hidden=clients.length>0;
  $('#quoteRows').innerHTML=[...db.quotes].reverse().map(q=>{const state=q.status==='fechado'?'Pago':q.status==='aprovado'?'Aprovado':'Pendente',kind=q.status==='fechado'?'closed':q.status==='aprovado'?'approved':'open';return `<tr><td class="quote-number">${esc(q.number)}</td><td>${esc(q.clientName||db.clients.find(c=>c.id===q.client)?.name||'—')}</td><td>${esc(q.description)}</td><td>${dateText(q.created)}</td><td class="row-value">${fmt(q.value)}</td><td><span class="quote-status ${kind}">${state}</span></td><td><button class="button secondary quote-pdf" data-open-quote="${esc(q.id)}">Abrir / PDF</button></td><td><div class="quote-row-actions">${q.status==='fechado'?`<button class="quote-reopen" data-reopen-quote="${esc(q.id)}">Reabrir</button>`:q.status==='aprovado'?`<button class="quote-close" data-close-quote="${esc(q.id)}">Registrar pagamento</button>`:`<button class="quote-approve" data-approve-quote="${esc(q.id)}">Aprovar</button>`}<button class="table-action" data-delete-quote="${esc(q.id)}" title="Excluir orçamento">×</button></div></td></tr>`}).join('');$('#quoteEmpty').hidden=db.quotes.length>0;
  renderDashboard();
 $('#quoteForm select[name="client"]').innerHTML='<option value="">Sem cliente vinculado</option>'+db.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');$('#buildClient').innerHTML='<option value="">Escolher cliente (opcional)</option>'+db.clients.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${esc(c.publicId||'')}</option>`).join('');renderParts();renderComponents();renderCatalog();renderNotes();renderDownloads();renderServiceOrders();renderManagementReport();renderBackupStatus();renderCashflow();sendReportClient();}
function renderCatalog(){const term=($('#catalogSearch')?.value||'').toLocaleLowerCase('pt-BR'),filter=$('[data-catalog-filter].active')?.dataset.catalogFilter||'Todos',category=$('#catalogCategoryFilter')?.value||'';const categories=[...new Set(db.catalog.map(i=>i.category||'Outros').filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'));const categorySelect=$('#catalogCategoryFilter'),current=categorySelect.value;categorySelect.innerHTML='<option value="">Todas as categorias</option>'+categories.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');if(categories.includes(current))categorySelect.value=current;const items=db.catalog.filter(item=>(filter==='Todos'||item.kind===filter)&&(!category||item.category===category)&&`${item.name} ${item.description||''} ${item.category||''}`.toLocaleLowerCase('pt-BR').includes(term));$('#catalogCount').textContent=`${items.length} ${items.length===1?'item':'itens'}`;$('#catalogGrid').innerHTML=items.map(item=>`<article class="catalog-card ${item.available===false?'unavailable':''}"><div class="catalog-card-top"><span class="catalog-type ${item.kind==='Serviço'?'service':'product'}">${esc(item.kind)}</span><span class="catalog-category">${esc(item.category||'Outros')}</span><button class="table-action" data-delete-catalog="${item.id}" title="Excluir item">×</button></div><h2>${esc(item.name)}</h2><p>${esc(item.description||'Sem descrição adicional')}</p><div class="catalog-meta"><span class="availability ${item.available===false?'off':''}">${item.available===false?'Indisponível':'Disponível'} para orçamento</span>${item.kind==='Produto'&&item.stock!==''&&item.stock!=null?`<span class="stock-label">${Number(item.stock)} em estoque</span>`:''}</div><div class="catalog-card-bottom"><strong>${fmt(item.price)}</strong><div><button class="catalog-text-button" data-edit-catalog="${item.id}">Editar</button><button class="catalog-use-button" data-add-catalog="${item.id}" ${item.available===false?'disabled':''}>Usar no orçamento ↗</button></div></div></article>`).join('');$('#catalogEmpty').hidden=items.length>0;}
function renderDownloads(){const term=($('#downloadSearch')?.value||'').toLocaleLowerCase('pt-BR'),select=$('#downloadCategoryFilter'),current=select.value,categories=[...new Set(db.downloads.map(x=>x.category||'Outros').filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'));select.innerHTML='<option value="">Todas as categorias</option>'+categories.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');if(categories.includes(current))select.value=current;const filter=select.value,items=[...db.downloads].filter(x=>(!filter||x.category===filter)&&`${x.name} ${x.description} ${x.version} ${x.category}`.toLocaleLowerCase('pt-BR').includes(term)).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));$('#downloadCount').textContent=`${items.length} ${items.length===1?'programa':'programas'}`;$('#downloadsGrid').innerHTML=items.map(x=>{const url=String(x.url||'').trim(),external=url.startsWith('https://'),safeUrl=external||(url.startsWith('downloads/')&&/^[A-Za-z0-9._/-]+$/.test(url)&&!url.includes('..')),icon=esc((x.name||'APP').trim().slice(0,3).toUpperCase());return `<article class="panel managed-download-card"><div class="managed-download-top"><span class="download-icon blue">${icon}</span><span class="download-type">${esc(x.category||'Outros')}</span><button class="download-delete" data-delete-download="${esc(x.id)}" title="Excluir programa" aria-label="Excluir ${esc(x.name)}">×</button></div><h2>${esc(x.name)}</h2><span class="download-version">Versão ${esc(x.version||'A informar')}</span><p>${esc(x.description||'Sem descrição.')}</p><div class="download-actions"><button class="download-edit" data-edit-download="${esc(x.id)}">Editar</button>${url&&safeUrl?`<a class="button primary" href="${esc(url)}" ${external?'target="_blank" rel="noopener noreferrer"':'download'}>Baixar programa ↓</a>`:`<button class="button secondary" data-edit-download="${esc(x.id)}">Configurar download</button>`}</div></article>`}).join('');$('#downloadsEmpty').hidden=items.length>0}
let clientEditId=null,activeHistoryClientId=null;
function clientHistoryItems(client){const same=(x)=>x.clientId===client.id||x.client===client.id||!!client.publicId&&(x.clientPublicId===client.publicId||x.formData?.cliente_id===client.publicId)||(!x.clientId&&!x.client&&String(x.clientName||'').trim().toLocaleLowerCase('pt-BR')===String(client.name||'').trim().toLocaleLowerCase('pt-BR'));const rows=[];db.quotes.filter(same).forEach(q=>rows.push({kind:'Orçamento',date:q.created||'',title:`${q.number||'Orçamento'} · ${q.description||'Proposta'}`,detail:q.status==='fechado'?'Pagamento registrado':q.status==='aprovado'?'Aprovado · aguardando pagamento':'Aguardando aprovação',status:q.status==='fechado'?'Pago':q.status==='aprovado'?'Aprovado':'Pendente',value:q.value||0}));db.serviceOrders.filter(same).forEach(o=>rows.push({kind:'Ordem de serviço',date:o.openedAt||o.created||'',title:`${o.number||'OS'} · ${o.equipment||'Atendimento técnico'}`,detail:[o.model,o.defect].filter(Boolean).join(' · '),status:serviceOrderStatuses[o.status]||o.status||'Aberta',value:o.total||0}));db.cashEntries.filter(same).forEach(x=>rows.push({kind:x.type==='entrada'?'Recebimento':'Despesa',date:x.date||x.created||'',title:x.description||x.category||'Lançamento financeiro',detail:x.category||'',status:cashIsSettled(x)?(x.type==='entrada'?'Recebido':'Pago'):(x.type==='entrada'?'A receber':'A pagar'),value:x.amount||0}));return rows.sort((a,b)=>String(b.date).localeCompare(String(a.date)))}
function showClientHistory(id){const client=db.clients.find(c=>c.id===id);if(!client)return;activeHistoryClientId=client.id;const rows=clientHistoryItems(client);$('#clientHistoryTitle').textContent=client.name;$('#clientHistorySubtitle').textContent=`ID ${client.publicId||'—'} · ${client.phone||client.whatsapp||'Sem telefone'}`;const quotes=rows.filter(x=>x.kind==='Orçamento').length,orders=rows.filter(x=>x.kind==='Ordem de serviço').length;$('#clientHistorySummary').innerHTML=`<span><b>${quotes}</b> orçamento(s)</span><span><b>${orders}</b> ordem(ns) de serviço</span><span><b>${rows.length}</b> registro(s) no total</span>`;$('#clientHistoryList').innerHTML=rows.map(x=>`<article class="client-history-item"><span class="client-history-icon ${x.kind==='Orçamento'?'quote':x.kind==='Ordem de serviço'?'os':'cash'}">${x.kind==='Orçamento'?'▤':x.kind==='Ordem de serviço'?'▣':'R$'}</span><div class="client-history-copy"><div><b>${esc(x.title)}</b><span class="client-history-status">${esc(x.status)}</span></div><p>${esc(x.kind)}${x.detail?` · ${esc(x.detail)}`:''}</p><small>${dateText(x.date)}</small></div><strong>${fmt(x.value)}</strong></article>`).join('');$('#clientHistoryEmpty').hidden=rows.length>0;$('#clientHistoryList').hidden=rows.length===0;$('#clientHistoryDialog').showModal()}
function startClientEditor(client=null){clientEditId=client?.id||null;const f=$('#clientForm');f.reset();f.elements.name.value=client?.name||'';f.elements.publicId.value=client?.publicId||newUserId();f.elements.phone.value=client?.phone||'';f.elements.whatsapp.value=client?.whatsapp||'';f.elements.email.value=client?.email||'';f.elements.address.value=client?.address||'';f.elements.notes.value=client?.notes||'';$('#clientDialogTitle').textContent=client?'Editar cliente':'Cadastrar cliente';$('#generateUserId').hidden=!!client;open('#clientDialog')}
