function renderServiceOrders(){const search=($('#osSearch')?.value||'').toLocaleLowerCase('pt-BR'),filter=$('#osStatusFilter')?.value||'',select=$('#serviceOrderForm select[name="client"]'),selected=select.value;select.innerHTML='<option value="">Selecione o cliente pelo ID</option>'+db.clients.map(c=>`<option value="${esc(c.id)}">ID ${esc(c.publicId||'—')} · ${esc(c.name)}</option>`).join('');if(db.clients.some(c=>c.id===selected))select.value=selected;const items=[...db.serviceOrders].sort((a,b)=>String(b.created||'').localeCompare(String(a.created||''))).filter(o=>(!filter||o.status===filter)&&`${o.number} ${o.clientName} ${o.clientPublicId} ${o.equipment} ${o.model} ${o.defect}`.toLocaleLowerCase('pt-BR').includes(search));$('#serviceOrderCount').textContent=db.serviceOrders.length;$('#osTotal').textContent=db.serviceOrders.length;$('#osActive').textContent=db.serviceOrders.filter(o=>!['pronta','entregue','cancelada'].includes(o.status)).length;$('#osCompleted').textContent=db.serviceOrders.filter(o=>['pronta','entregue'].includes(o.status)).length;$('#osResultCount').textContent=`${items.length} ${items.length===1?'ordem':'ordens'}`;$('#serviceOrderRows').innerHTML=items.map(o=>{const status=o.status||'aberta',photo=String(o.photo||'').startsWith('data:image/')?`<img class="os-table-photo" src="${esc(o.photo)}" alt="Foto do equipamento">`:'<span class="os-no-photo">—</span>',linked=db.quotes.find(q=>q.serviceOrderId===o.id||q.id===o.quoteId);return `<tr><td><b class="os-number">${esc(o.number)}</b><small class="os-date">Entrada ${dateText(o.openedAt||o.created)}</small></td><td><b>${esc(o.clientName||'Cliente removido')}</b><small class="os-client-id">ID ${esc(o.clientPublicId||'—')}</small></td><td><div class="os-equipment-cell">${photo}<span><b>${esc(o.equipment||'Equipamento')}</b><small>${esc(o.model||'Modelo não informado')}</small></span></div></td><td class="os-defect-cell">${esc(o.defect||'—')}</td><td><span class="os-status ${esc(status)}">${esc(serviceOrderStatuses[status]||status)}</span></td><td class="os-value">${fmt(o.total)}</td><td><div class="os-row-actions"><button class="os-action" data-edit-os="${esc(o.id)}">Editar</button><button class="os-action" data-print-os="${esc(o.id)}">PDF</button><button class="os-action os-quote-action" data-os-quote="${esc(o.id)}">${linked?'Ver orçamento':'Gerar orçamento'}</button><button class="os-delete" data-delete-os="${esc(o.id)}" title="Excluir OS" aria-label="Excluir ${esc(o.number)}">×</button></div></td></tr>`}).join('');$('#serviceOrdersEmpty').hidden=items.length>0}
function nextServiceOrderNumber(){const year=new Date().getFullYear(),prefix=`OS-${year}-`,max=db.serviceOrders.reduce((n,o)=>{const match=String(o.number||'').match(new RegExp(`^OS-${year}-(\\d+)$`));return match?Math.max(n,Number(match[1])):n},0);return `${prefix}${String(max+1).padStart(4,'0')}`}
