function shortMoney(n){const v=Number(n)||0;return v>=1e6?`R$ ${(v/1e6).toFixed(1)} mi`:v>=1000?`R$ ${(v/1000).toFixed(1)} mil`:fmt(v)}
function drawCashChart(entries,target='#cashChart'){const totals=monthLabels.map((_,i)=>({in:0,out:0}));entries.filter(cashIsSettled).forEach(x=>{const date=String(x.settledAt||x.date||''),m=Number(date.slice(5,7))-1;if(m<0||m>11)return;totals[m][x.type==='entrada'?'in':'out']+=Number(x.amount)||0});const max=Math.max(1,...totals.flatMap(x=>[x.in,x.out])),base=204,height=150,step=68,start=60,scale=height/max;let svg='<svg viewBox="0 0 880 250" role="img" aria-label="Gráfico de recebimentos e pagamentos">';for(let i=0;i<=3;i++){const y=base-(height*i/3);svg+=`<line x1="42" y1="${y}" x2="865" y2="${y}" class="chart-gridline"/><text x="36" y="${y-4}" class="chart-axis" text-anchor="end">${shortMoney(max*i/3)}</text>`}totals.forEach((m,i)=>{const x=start+i*step,hin=Math.max(m.in?2:0,m.in*scale),hout=Math.max(m.out?2:0,m.out*scale);svg+=`<rect x="${x}" y="${base-hin}" width="18" height="${hin}" rx="4" class="chart-bar-in"><title>${monthLabels[i]}: recebidos ${fmt(m.in)}</title></rect><rect x="${x+22}" y="${base-hout}" width="18" height="${hout}" rx="4" class="chart-bar-out"><title>${monthLabels[i]}: pagos ${fmt(m.out)}</title></rect><text x="${x+20}" y="228" class="chart-month" text-anchor="middle">${monthLabels[i]}</text>`});svg+='</svg>';$(target).innerHTML=svg}
